dependents = {t.name: [] for t in tasks}
for t in tasks:
    for d in t.depends_on:
        dependents[d].append(t.name)
# dependents["setup"] now lists every task waiting on setup

def longest_chain(name):
    if name not in critical_length:
        successors = dependents[name]
        duration = scheduler.get_task(name).duration
        critical_length[name] = duration + (
            max(longest_chain(s) for s in successors) if successors else 0
        )
    return critical_length[name]
# leaf task (no successors) just returns its own duration
